{"command": "cat <<'EOF' > /tmp/webptest.c
#include <dlfcn.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

int main() {
    void* h = dlopen("libwebp.so.7", RTLD_NOW);
    if (!h) { printf("dlopen fail %s\n", dlerror()); return 1; }
    int (*WebPGetInfo)(const uint8_t*, size_t, int*, int*) = dlsym(h, "WebPGetInfo");
    uint8_t* (*WebPDecodeRGB)(const uint8_t*, size_t, int*, int*) = dlsym(h, "WebPDecodeRGB");
    void (*WebPFree)(void*) = dlsym(h, "WebPFree");
    size_t (*WebPEncodeRGB)(const uint8_t*, int, int, int, float, uint8_t**) = dlsym(h, "WebPEncodeRGB");
    printf("syms %p %p %p %p\n", WebPGetInfo, WebPDecodeRGB, WebPFree, WebPEncodeRGB);
    FILE* f = fopen("assets/w0.webp","rb");
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    uint8_t* data=malloc(sz); fread(data,1,sz,f); fclose(f);
    int w,h;
    int ok = WebPGetInfo(data, sz, &w, &h);
    printf("info ok=%d w=%d h=%d\n", ok, w, h);
    int dw,dh;
    uint8_t* rgb = WebPDecodeRGB(data, sz, &dw, &dh);
    printf("decode %p w=%d h=%d\n", rgb, dw, dh);
    if (rgb) {
        uint8_t* out=NULL;
        size_t outsz = WebPEncodeRGB(rgb, dw, dh, dw*3, 80.0f, &out);
        printf("encode size=%zu\n", outsz);
        if (out) WebPFree(out);
        WebPFree(rgb);
    }
    free(data);
    dlclose(h);
    return 0;
}
EOF
gcc /tmp/webptest.c -ldl -o /tmp/webptest && /tmp/webptest"}

