func formatSize(b int64) string {
	if b < 1024 {
		return fmt.Sprintf("%d B", b)
	} else if b < 1024*1024 {
		return fmt.Sprintf("%.1f KiB", float64(b)/1024.0)
	} else if b < 1024*1024*1024 {
		return fmt.Sprintf("%.1f MiB", float64(b)/(1024.0*1024.0))
	} else {
		return fmt.Sprintf("%.1f GiB", float64(b)/(1024.0*1024.0*1024.0))
	}
}

func formatDelta(d int64) string {
	if d == 0 {
		return "-0 B"
	}
	sign := "+"
	if d < 0 {
		sign = "-"
		d = -d
	}
	return sign + formatSize(d)
}

func formatPercent(input, output int64) string {
	if input == 0 {
		return "-0.00%"
	}
	p := float64(output-input) / float64(input) * 100.0
	if p == 0 {
		return "-0.00%"
	}
	sign := "+"
	if p < 0 {
		sign = "-"
		p = -p
	}
	// Need to handle -0.00% for very small? Already handled p==0.
	return fmt.Sprintf("%s%.2f%%", sign, p)
}

func formatLine(input, output int64) string {
	return fmt.Sprintf("%s -> %s [%s | %s]", formatSize(input), formatSize(output), formatDelta(output-input), formatPercent(input, output))
}

