func computeBasePath(files []string, cfg *Config) string {
	if !cfg.KeepStructure {
		return ""
	}
	if len(files) == 0 {
		return ""
	}
	if len(files) == 1 {
		// For single file, base is parent? But output is flat, so base not used? Return parent?
		return filepath.Dir(files[0])
	}
	// Find common ancestor of all files/dirs? For files, common dir?
	// Observed: for /tmp/b1/a.jpg and /tmp/b2/b.png, base is /tmp (common ancestor), outputs b1/a.jpg, b2/b.png
	// For /tmp/tree with -R -S, base is /tmp/tree, outputs a/b/c.jpg etc.
	// For explicit files in same dir, base is that dir? For /tmp/samedir/a.jpg + b.png, outputs flat (since relative is just basename)? Actually with -S, outputs were flat (a.jpg, b.png), not samedir/a.jpg. Wait earlier: two files same dir with -S gave flat (a.jpg, b.png), not with prefix. So base is /tmp/samedir, relative is basename. Good.
	// So base is common dir.
	dirs := make([]string, len(files))
	for i, f := range files {
		// Use absolute?
		abs, err := filepath.Abs(f)
		if err != nil {
			abs = f
		}
		dirs[i] = filepath.Dir(abs)
	}
	// Find common prefix
	common := dirs[0]
	for _, d := range dirs[1:] {
		common = commonDir(common, d)
	}
	return common
}

func commonDir(a, b string) string {
	// Find common ancestor directory
	a = filepath.Clean(a)
	b = filepath.Clean(b)
	// Split
	aa := strings.Split(a, string(os.PathSeparator))
	bb := strings.Split(b, string(os.PathSeparator))
	n := 0
	for n < len(aa) && n < len(bb) && aa[n] == bb[n] {
		n++
	}
	if n == 0 {
		return string(os.PathSeparator)
	}
	return strings.Join(aa[:n], string(os.PathSeparator))
}

