		needResize = true
	}
	if cfg.Height != nil && *cfg.Height != 0 {
		needResize = true
	}
	if cfg.LongEdge != nil && *cfg.LongEdge != 0 {
		needResize = true
	}
	if cfg.ShortEdge != nil && *cfg.ShortEdge != 0 {
