	rgba := image.NewRGBA(bounds)
	for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
		for x := bounds.Min.X; x < bounds.Max.X; x++ {
			rgba.Set(x, y, img.At(x, y))
		}
	}
	// TIFF structure: header (8) + IFD + data
	// We'll write: header, IFD with 10 entries? Let's write minimal: Width, Height, BitsPerSample, Compression=1, Photometric=2, StripOffsets, RowsPerStrip, StripByteCounts, XResolution, YResolution, ResolutionUnit?
