	// BitsPerSample needs array of 3 shorts (for RGB)
	// Data layout: header (8) + IFD (2 + 12*8 + 4) + BitsPerSample array (6) + image data (w*h*3)
	numEntries := 8
	ifdSize := 2 + numEntries*12 + 4
	bitsOffset := 8 + ifdSize
	dataOffset := bitsOffset + 6
	stripSize := width * height * 3

	// Header
	w.Write([]byte{'I', 'I', 42, 0})
	writeU32 := func(v uint32) {
		w.Write([]byte{byte(v), byte(v >> 8), byte(v >> 16), byte(v >> 24)})
	}
	writeU16 := func(v uint16) {
		w.Write([]byte{byte(v), byte(v >> 8)})
	}
	writeU32(8) // IFD offset
	// IFD
	writeU16(uint16(numEntries))
	// Helper to write entry
	writeEntry := func(tag, typ uint16, count uint32, val uint32) {
		writeU16(tag)
		writeU16(typ)
		writeU32(count)
		writeU32(val)
	}
	// Types: 3=SHORT, 4=LONG
	writeEntry(256, 4, 1, uint32(width))   // ImageWidth
	writeEntry(257, 4, 1, uint32(height))  // ImageLength
	writeEntry(258, 3, 3, uint32(bitsOffset)) // BitsPerSample (offset)
	writeEntry(259, 3, 1, 1) // Compression = 1 (none)
	writeEntry(262, 3, 1, 2) // Photometric = 2 (RGB)
	writeEntry(273, 4, 1, uint32(dataOffset)) // StripOffsets
	writeEntry(278, 4, 1, uint32(height)) // RowsPerStrip
	writeEntry(279, 4, 1, uint32(stripSize)) // StripByteCounts
	writeU32(0) // next IFD
	// BitsPerSample array: 3x SHORT (8,8,8)
	writeU16(8)
	writeU16(8)
	writeU16(8)
	// Image data: RGB
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			c := rgba.RGBAAt(bounds.Min.X+x, bounds.Min.Y+y)
			w.Write([]byte{c.R, c.G, c.B})
		}
	}
	return nil
}

