func webpDecode(data []byte) (image.Image, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty")
	}
	cdata := C.malloc(C.size_t(len(data)))
	if cdata == nil {
		return nil, fmt.Errorf("malloc")
	}
	defer C.free(cdata)
	// copy
