python3 - <<'PY'
import subprocess, os, shutil
def run_new(*args):
    p = subprocess.run(["bash","-c","exec -a executable /tmp/testbin "+ " ".join(f"'{a}'" for a in args)], capture_output=True, text=True)
    return p
def run_orig(*args):
    p = subprocess.run(["./executable"]+list(args), capture_output=True, text=True)
    return p
for args in [["--lossless","-o","/tmp/out","--verbose","0","/tmp/corrupt.jpg"], ["--lossless","-o","/tmp/out","-Q","/tmp/corrupt.jpg"], ["-q","80","-o","/tmp/out","--verbose","0","/nonexistent"], ["--lossless","-o","/tmp/out","--verbose","0"], ["-q","80","-o","/tmp/out","-Q","/nonexistent"]]:
    shutil.rmtree("/tmp/out", ignore_errors=True)
    o = run_orig(*args)
    shutil.rmtree("/tmp/out", ignore_errors=True)
    n = run_new(*args)
    import re
    def norm(s): return re.sub(r"\(\d+\)", "(XXX)", s)
    ok = (o.stdout==n.stdout and norm(o.stderr)==norm(n.stderr) and o.returncode==n.returncode)
    print(f"{'OK' if ok else 'DIFF'} {args}")
    if not ok:
        print(" orig OUT:", repr(o.stdout), "ERR:", repr(o.stderr)[:500])
        print(" new  OUT:", repr(n.stdout), "ERR:", repr(n.stderr)[:500])
